const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Helper to await EE evaluate
  const eeGet = (obj) =>
    new Promise((resolve, reject) => obj.evaluate((res, err) => err ? reject(err) : resolve(res)));

  // 1. Geometry & Time Definitions
  const lon = 141.780304;
  const lat = -27.667421;
  const aoi = ee.Geometry.Point([lon, lat]).buffer(10000); // 10 km radius
  const scale = 1000;
  const date1Str = '2025-04-06';
  const date2Str = '2025-04-22';
  const date1 = ee.Date(date1Str);
  const date2 = ee.Date(date2Str);

  console.log(`AOI center: (${lat.toFixed(6)}, ${lon.toFixed(6)}), radius: 10 km`);

  // Collections
  const s2ColBase = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED');
  const l8Col = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2');
  const l9Col = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2');
  const landsatColBase = l8Col.merge(l9Col);

  // Cloud masking
  function maskS2(img) {
    const qa60 = img.select('QA60');
    const scl = img.select('SCL');
    const mask = qa60.bitwiseAnd(1 << 10).eq(0)
      .and(qa60.bitwiseAnd(1 << 11).eq(0))
      .and(scl.neq(3))   // cloud shadow
      .and(scl.neq(8))   // medium cloud
      .and(scl.neq(9))   // high cloud
      .and(scl.neq(10))  // cirrus
      .and(scl.neq(11)); // snow/ice
    return img.updateMask(mask);
  }
  function maskLandsat(img) {
    const qa = img.select('QA_PIXEL');
    const clear = qa.bitwiseAnd(1 << 1).eq(0)  // dilated cloud
      .and(qa.bitwiseAnd(1 << 2).eq(0))       // cirrus
      .and(qa.bitwiseAnd(1 << 3).eq(0))       // cloud
      .and(qa.bitwiseAnd(1 << 4).eq(0));      // cloud shadow
    return img.updateMask(clear);
  }

  // NDVI builders
  function ndviS2(img) {
    const masked = maskS2(img);
    return masked.normalizedDifference(['B8', 'B4']).rename('NDVI');
  }
  function ndviLandsat(img) {
    const masked = maskLandsat(img);
    const scaled = masked.select(['SR_B4', 'SR_B5']).multiply(0.0000275).add(-0.2);
    return scaled.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDVI');
  }

  // Select closest image within a window
  async function getClosest(colBase, targetDate, windowDays, isS2) {
    const start = ee.Date(targetDate).advance(-windowDays, 'day');
    const end = ee.Date(targetDate).advance(windowDays + 1, 'day'); // inclusive window
    let col = colBase.filterBounds(aoi).filterDate(start, end);
    // Add time diff in days
    col = col.map(img => img.set('diffDays', ee.Number(img.date().difference(targetDate, 'day')).abs()));
    const size = await eeGet(col.size());
    if (!size || size === 0) return { size: 0, img: null };
    // Sort by time difference then by cloud property if present
    const sorted = col.sort('diffDays').sort(isS2 ? 'CLOUDY_PIXEL_PERCENTAGE' : 'CLOUD_COVER');
    const img = sorted.first();
    return { size, img };
  }

  async function processDate(dateStr, targetDate) {
    // Try Sentinel-2 within ±3, then ±7
    let used = null;
    let collectionNote = '';
    let s2Try = await getClosest(s2ColBase, targetDate, 3, true);
    if (s2Try.size === 0) s2Try = await getClosest(s2ColBase, targetDate, 7, true);
    if (s2Try.size > 0) {
      used = { img: s2Try.img, sensor: 'S2', imgs: s2Try.size };
      collectionNote = `S2 imgs ${s2Try.size}`;
    } else {
      // Fallback to Landsat within ±3, then ±7
      let lsTry = await getClosest(landsatColBase, targetDate, 3, false);
      if (lsTry.size === 0) lsTry = await getClosest(landsatColBase, targetDate, 7, false);
      if (lsTry.size > 0) {
        used = { img: lsTry.img, sensor: 'Landsat', imgs: lsTry.size };
        collectionNote = `Landsat imgs ${lsTry.size}`;
      }
    }
    if (!used) {
      return { status: 'C1', line: `${dateStr} -> No images found (S2/Landsat)` };
    }

    // Build NDVI and compute stats
    const img = used.img;
    const sensor = used.sensor;
    const ndvi = (sensor === 'S2') ? ndviS2(img) : ndviLandsat(img);

    const totalCountDict = ee.Image(1).rename('const').reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: aoi,
      scale: scale,
      maxPixels: 1e9,
      bestEffort: true
    });
    const validCountDict = ndvi.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: aoi,
      scale: scale,
      maxPixels: 1e9,
      bestEffort: true
    });
    const meanDict = ndvi.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: aoi,
      scale: scale,
      maxPixels: 1e9,
      bestEffort: true
    });

    const totals = await eeGet(totalCountDict);
    const valids = await eeGet(validCountDict);
    const means = await eeGet(meanDict);

    const totalCount = totals ? (totals.const || 0) : 0;
    const validCount = valids ? (valids.NDVI || 0) : 0;
    if (!totalCount || validCount === 0) {
      // Images exist but all masked
      // Get date and cloud to print context
      const props = await eeGet(img.toDictionary(['system:time_start', 'CLOUDY_PIXEL_PERCENTAGE', 'CLOUD_COVER']));
      const usedDate = props && props['system:time_start'] ? new Date(props['system:time_start']).toISOString().slice(0,10) : 'n/a';
      const sc = props && (props.CLOUDY_PIXEL_PERCENTAGE ?? props.CLOUD_COVER);
      const scTxt = (sc === null || sc === undefined) ? 'n/a' : `${Number(sc).toFixed(1)}%`;
      return {
        status: 'C2',
        line: `${dateStr} -> ${sensor}: ${collectionNote}, used ${usedDate}, sceneCld ${scTxt}, valid 0/${totalCount || 'n/a'} (0.0%), NDVI n/a`
      };
    }

    const mean = means ? means.NDVI : null;
    if (mean === null || isNaN(mean) || mean < -1.5 || mean > 1.5) {
      return { status: 'C3', line: `${dateStr} -> Calculation failure (NDVI=${mean})` };
    }

    const props = await eeGet(img.toDictionary(['system:time_start', 'CLOUDY_PIXEL_PERCENTAGE', 'CLOUD_COVER']));
    const usedDate = props && props['system:time_start'] ? new Date(props['system:time_start']).toISOString().slice(0,10) : 'n/a';
    const sc = props && (props.CLOUDY_PIXEL_PERCENTAGE ?? props.CLOUD_COVER);
    const scTxt = (sc === null || sc === undefined) ? 'n/a' : `${Number(sc).toFixed(1)}%`;
    const coverage = 100 * (validCount / totalCount);
    const line = `${dateStr} -> ${sensor}: ${collectionNote}, used ${usedDate}, sceneCld ${scTxt}, valid ${validCount}/${totalCount} (${coverage.toFixed(1)}%), NDVI ${Number(mean).toFixed(3)}`;
    return { status: 'OK', line, mean, usedDate, sensor, sceneCloud: sc };
  }

  try {
    const res1 = await processDate(date1Str, date1);
    console.log(res1.line);
    if (res1.status !== 'OK') {
      console.log(res1.status);
      return;
    }
    const res2 = await processDate(date2Str, date2);
    console.log(res2.line);
    if (res2.status !== 'OK') {
      console.log(res2.status);
      return;
    }

    const delta = res2.mean - res1.mean;
    console.log(`Delta NDVI (22 - 06): ${delta.toFixed(3)}`);

    if (delta > 0) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.log(`Error: ${String(err).slice(0,180)}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
